-- Awards on bar profiles, and the most interesting cocktail bars in New York,
-- London, Paris, Hong Kong, Singapore, Sydney and Melbourne, with their
-- signature drinks.
--
-- 1. public.profile_awards: list places and titles a bar (or a person) has
--    won, e.g. No. 6 on The World's 50 Best Bars 2025, or the Spirited Awards'
--    World's Best Cocktail Bar. Anyone reads a public profile's awards; only
--    catalog admins (and SQL / the service role) write them.
--    ponytail: awards are curated by hand from each list's own site. When the
--    lists publish yearly, a follow-up migration (or an admin screen, if this
--    grows) adds the new year.
--
-- 2. The 50 bars from The World's 50 Best Bars 2025 get that place as an
--    award (it was only in their bios until now).
--
-- 3. 68 more bars in the seven cities as public, unclaimed venue
--    profiles, same rules as the 50 Best seed: a bar already here (same name
--    within 150 m, or the handle taken) is left alone, and each bar claims its
--    profile the usual way. Addresses and points were checked against
--    OpenStreetMap on 29 Sep 2026.
--
-- 4. 246 signature drinks, as shared drinks credited to the bar they
--    come from (origin_bar_profile_id), so they show under the bar's
--    Originals and can be ranked there. A drink that's a version of a classic
--    links to the catalog entry (riff_of_id), so it ranks in that classic's
--    list. Descriptions are ours and name the main ingredients; they are not
--    the bars' menu copy. No specs: a bar that claims its profile adds its own.
--
-- 5. app_item_presentation gains origin_bar_profile_id and created_by (added
--    at the end, nothing else changes), so the Library can leave out drinks
--    credited to other bars: they belong on those bars' profiles, not in
--    everyone's personal list.

-- --- Awards ---

CREATE TABLE "public"."profile_awards" (
    "id" "uuid" DEFAULT "gen_random_uuid"() PRIMARY KEY,
    "profile_id" "uuid" NOT NULL REFERENCES "public"."profiles"("id") ON DELETE CASCADE,
    -- The list or awards body, e.g. 'The World''s 50 Best Bars'.
    "award" "text" NOT NULL CHECK (char_length(btrim("award")) BETWEEN 1 AND 80),
    "year" smallint NOT NULL CHECK ("year" BETWEEN 1990 AND 2100),
    -- A list place (No. 1-500), or null for a titled award.
    "position" smallint CHECK ("position" BETWEEN 1 AND 500),
    -- A category or special award, e.g. 'World''s Best Cocktail Bar'.
    "title" "text" CHECK (char_length(btrim("title")) BETWEEN 1 AND 80),
    "source_url" "text" CHECK ("source_url" ~ '^https://'),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "profile_awards_has_place_or_title" CHECK ("position" IS NOT NULL OR "title" IS NOT NULL)
);

CREATE UNIQUE INDEX "profile_awards_unique" ON "public"."profile_awards" ("profile_id", "award", "year", coalesce("title", ''));

ALTER TABLE "public"."profile_awards" ENABLE ROW LEVEL SECURITY;

-- Anyone, signed in or not, reads a public profile's awards. (Inline check:
-- anon can't call private helpers; profiles' own RLS applies inside.)
CREATE POLICY "profile_awards_select" ON "public"."profile_awards" FOR SELECT TO "anon", "authenticated"
    USING (EXISTS (SELECT 1 FROM "public"."profiles" p WHERE p.id = "profile_id" AND p.is_public));
CREATE POLICY "profile_awards_admin" ON "public"."profile_awards" FOR ALL TO "authenticated"
    USING ("private"."is_app_admin"()) WITH CHECK ("private"."is_app_admin"());

GRANT SELECT ON TABLE "public"."profile_awards" TO "anon", "authenticated";
GRANT INSERT, UPDATE, DELETE ON TABLE "public"."profile_awards" TO "authenticated";
GRANT ALL ON TABLE "public"."profile_awards" TO "service_role";

-- --- Library: leave out other bars' credited drinks ---

CREATE OR REPLACE VIEW "public"."app_item_presentation" WITH ("security_invoker" = true) AS
 SELECT c.id,
    c.name,
    c.item_type,
    c.description,
    c.created_at,
    c.glassware_id,
    c.family_id,
    c.ice_id,
    c.notes,
    c.origin,
    c.price,
    c.status,
    c.brand_maker,
    c.abv,
    c.bar_id,
    c.icon_key,
    c.icon_url,
    c.hide_from_search,
    c.origin_bar_profile_id,
    c.created_by
   FROM public.items c
     LEFT JOIN public.bars b ON c.bar_id = b.id
     LEFT JOIN public.user_bars ub ON ub.bar_id = c.bar_id AND ub.user_id = auth.uid()
  WHERE c.bar_id IS NULL OR public.effective_bar_role(ub.role_level) >= COALESCE(c.override_visibility_level, b.default_visibility_level);

-- --- The bars ---

INSERT INTO "public"."profiles" ("kind", "handle", "display_name", "bio", "website", "is_public", "locality", "address_line",
                                 "postcode", "city", "region", "country_code", "latitude", "longitude")
SELECT 'bar', v.handle, v.name, v.bio, v.website, true, v.locality, v.address_line,
       v.postcode::text, v.city, v.region::text, v.country_code, v.latitude, v.longitude
FROM (VALUES
    ('schmuck.ny', 'schmuck.', 'East Village cocktail bar from Moe Aljaff and Juliette Larrouy, the duo behind Barcelona''s Two Schmucks, opened in January 2025 on the corner of First Avenue and 6th Street. Two rooms, a lounge-style living room and a communal kitchen table, each with its own menu of ingredient-led drinks and Middle Eastern and European bar food. No. 4 on North America''s 50 Best Bars 2026.', 'https://www.schmucknyc.com/', 'East Village', '97 1st Avenue', '10003', 'New York', 'New York', 'US', 40.72639, -73.98641),
    ('barsnack.nyc', 'Bar Snack', 'A 1970s-flavoured neighbourhood bar on Second Avenue in the East Village, led by bartender Iain Griffiths and opened in late 2024. Its motto is dressed-up classics for dressed-down people, and its name comes from the snaquiri, a small pour of the seasonal house daiquiri that also comes by the glass or pitcher. Named Best U.S. Cocktail Bar at the 2026 Spirited Awards. No. 3 on North America''s 50 Best Bars 2026.', 'https://www.barsnacknyc.com/', 'East Village', '92 2nd Avenue', '10003', 'New York', 'New York', 'US', 40.72699, -73.98862),
    ('theclementebar', 'Clemente Bar', 'Art-filled cocktail lounge one floor above Eleven Madison Park, born from a collaboration between chef Daniel Humm and painter Francesco Clemente, whose works line the room. Opened in late 2024 with a rotating menu of technical but restrained cocktails and plant-based bar bites, plus The Studio, a nine-seat chef''s counter next door. No. 15 on North America''s 50 Best Bars 2026.', 'https://www.clementebar.com/', 'Flatiron', '11 Madison Avenue', '10010', 'New York', 'New York', 'US', 40.7416, -73.98719),
    ('martinys_nyc', 'Martiny''s', 'Japanese-style cocktail bar spread over three floors of an 1800s Gramercy carriage house once used by sculptor Philip Martiny. Opened in 2022 by Tokyo-born Takuma Watanabe after eight years as head bartender of Angel''s Share, it pairs omotenashi hospitality and crystal glassware with a course-by-course cocktail list. Watanabe was U.S. Bartender of the Year at the 2026 Spirited Awards. No. 23 on North America''s 50 Best Bars 2026.', 'https://www.martinys.com/', 'Gramercy', '121 East 17th Street', '10003', 'New York', 'New York', 'US', 40.73615, -73.98771),
    ('attaboy134', 'Attaboy', 'Unsigned Lower East Side bar opened in 2013 by Sam Ross and Michael McIlroy in the Eldridge Street room that was once Sasha Petraske''s Milk & Honey, where both trained. There is no menu: bartenders ask what you like and build a drink to match. Ross and McIlroy created modern classics such as the Penicillin and Greenpoint. No. 37 on North America''s 50 Best Bars 2026.', 'https://attaboy.us/', 'Lower East Side', '134 Eldridge Street', '10002', 'New York', 'New York', 'US', 40.71888, -73.99137),
    ('employeesonlyny', 'Employees Only', 'West Village bar and restaurant opened in 2004 by five industry friends (Dushan Zaric, Henry LaFargue, Igor Hadzismajlovic, Jason Kosmas and Bill Gilroy), entered past a fortune teller''s booth. A training ground for a generation of bartenders, known for its house Manhattan, the Amelia and late-night food. World''s Best Cocktail Bar at the 2011 Spirited Awards. No. 78 on The World''s 50 Best Bars 2026.', 'https://www.employeesonlynyc.com/', 'West Village', '510 Hudson Street', '10014', 'New York', 'New York', 'US', 40.73343, -74.00608),
    ('thedeadrabbitny', 'The Dead Rabbit', 'Irish pub and cocktail bar opened in 2013 at 30 Water Street by Belfast bartenders Sean Muldoon and Jack McGarry; McGarry still runs it. A Guinness-pouring Taproom downstairs and The Parlor, a cocktail room upstairs, plus a famous Irish Coffee. It was No. 1 on The World''s 50 Best Bars 2016 and World''s Best Bar at the 2015 Spirited Awards.', 'https://www.thedeadrabbit.com/', 'Financial District', '30 Water Street', '10004', 'New York', 'New York', 'US', 40.70325, -74.01101),
    ('maisonpremiere', 'Maison Premiere', 'Williamsburg oyster bar and cocktail den opened in 2011 by Joshua Boissy and Krystof Zizka, modelled on the absinthe cafes and grand oyster houses of New Orleans and Paris. It has one of the largest absinthe lists in the US, poured from a replica of the Old Absinthe House fountain, plus juleps, Sazeracs and a tableside martini. No. 40 on North America''s 50 Best Bars 2026.', 'https://maisonpremiere.com/', 'Williamsburg, Brooklyn', '298 Bedford Avenue', '11249', 'New York', 'New York', 'US', 40.71424, -73.9616),
    ('kwantmayfair', 'Kwãnt Mayfair', 'Erik Lorincz, the former head bartender of the American Bar at The Savoy, first opened Kwãnt off Regent Street in 2019 and relaunched it in 2023 on a Mayfair corner by Green Park. The room leans tropical, with cane, palms and ceiling fans, and the drinks lean on ferments and unusual distillates, served by bartenders working stations around the counter. No. 79 on The World''s 50 Best Bars 2025.', 'https://www.instagram.com/kwantmayfair/', 'Mayfair', '52 Stratton Street', 'W1J 8LN', 'London', NULL, 'GB', 51.50719, -0.14329),
    ('threesheetssoho', 'Three Sheets Soho', 'Brothers Max and Noel Venning took the Three Sheets formula from their original Dalston bar to a Manette Street site in Soho in 2024. Menus are short and built on pared-back, seasonal twists on modern classics, with a carbonated French 75 as the calling card, plus oysters and a proper burger from the kitchen. No. 73 on The World''s 50 Best Bars 2026 (51-100).', 'https://www.threesheets-bar.com/soho', 'Soho', '13 Manette Street', 'W1D 4AP', 'London', NULL, 'GB', 51.51473, -0.13096),
    ('abarwithshapesforaname', 'A Bar with Shapes for a Name', 'Remy Savage and Paul Lougrat opened this Kingsland Road bar in May 2021, naming it with a yellow triangle, red square and blue circle. The whole concept borrows from the Bauhaus: a spare, functional room and short menus where each drink is designed around a single lead flavour, with classics on request. No. 73 on The World''s 50 Best Bars 2025 (51-100).', 'https://www.clubbauhaus.com/abarwithshapesforaname', 'Haggerston', '232 Kingsland Road', 'E2 8AX', 'London', NULL, 'GB', 51.53561, -0.07672),
    ('waltzbar', 'Waltz', 'Tokyo-born bartender Gento Torigata, formerly of Kwãnt, opened Waltz in spring 2025 behind a discreet door on Scrutton Street. About a dozen seats face a long elm counter, jazz plays through custom speakers, and the Japanese-style menu splits into evergreen signatures and drinks that shift with Japan''s 72 micro-seasons. No. 23 on Europe''s 50 Best Bars 2026.', 'https://waltzbar.uk/', 'Shoreditch', '28 Scrutton Street', 'EC2A 4RP', 'London', NULL, 'GB', 51.5232, -0.08289),
    ('sidehustlelondon', 'Side Hustle', 'The cocktail bar of NoMad London, opened in 2021 inside the former Bow Street police station and magistrates'' court in Covent Garden. Around a marble-topped bar and green leather booths, it pairs a Latin American-leaning, agave-focused cocktail list with tacos and snacks. Best International Hotel Bar at the 2025 Spirited Awards.', 'https://www.hilton.com/en/hotels/lonnmnd-nomad-london/dining/side-hustle/', 'Covent Garden', '28 Bow Street', 'WC2E 7AW', 'London', NULL, 'GB', 51.51351, -0.1221),
    ('americanbarsavoy', 'American Bar', 'The Savoy''s American Bar opened in 1893 and the hotel calls it London''s original cocktail bar. Harry Craddock and Ada Coleman both worked here, and Coleman''s Hanky Panky was born at The Savoy. Today''s menu tells stories from the hotel''s history alongside vintage spirits and classics. It was No. 1 on The World''s 50 Best Bars 2017 and the Spirited Awards'' World''s Best Bar 2018.', 'https://www.thesavoylondon.com/restaurants-and-bars/american-bar', 'Covent Garden', 'The Savoy, Strand', 'WC2R 0EZ', 'London', NULL, 'GB', 51.51013, -0.1205),
    ('lyanessbar', 'Lyaness', 'Ryan Chetiyawardana (Mr Lyan) opened Lyaness in March 2019 at Sea Containers London on the South Bank, in the room that had housed his Dandelyan. The menu is organised around house-made ingredients rather than classic templates, built through ferments and collaborations, and served over Dandelyan''s original green marble bar. World''s Best Bar at the 2022 Spirited Awards.', 'https://www.lyaness.com/', 'South Bank', 'Sea Containers London, 20 Upper Ground', 'SE1 9PD', 'London', NULL, 'GB', 51.50857, -0.10674),
    ('officialcafepacifico', 'Café Pacifico', 'A Covent Garden Mexican restaurant and tequila bar, open since 1982, that calls itself London''s oldest and says it was the first to bring Mexican food and tequila to the UK. Margaritas are the core of the list, alongside a long agave selection and mezcal drinks, and its bartenders have repeatedly won London''s Margarita Rumble. Timeless International Award at the 2024 Spirited Awards.', 'https://cafe-pacifico.com/', 'Covent Garden', '5 Langley Street', 'WC2H 9JA', 'London', NULL, 'GB', 51.51315, -0.1251),
    ('swiftsoho', 'Swift Soho', 'Mia Johansson and Bobby Hiddleston opened Swift on Old Compton Street in November 2016, the first of three Swift bars. Upstairs is a walk-in room for quick aperitivo-style drinks; the booked basement pours more involved cocktails, hosts live jazz and holds a whisky list of more than 300 bottles. Its Irish Coffee has become one of the city''s signature serves.', 'https://www.barswift.com/swift-soho', 'Soho', '12 Old Compton Street', 'W1D 4TQ', 'London', NULL, 'GB', 51.51374, -0.12999),
    ('littlereddoor_paris', 'Little Red Door', 'Unsigned speakeasy behind a red door on Rue Charlot, co-founded in 2012 by Timothée Prangé and long a fixture on The World''s 50 Best Bars. Since July 2024 it has been run by Hugo Gallou and Hyacinthe Lescoët of The Cambridge Public House. The current Agri/Culture menu turns farming techniques into drinks built on French producers. No. 93 on The World''s 50 Best Bars 2026 (51-100).', 'https://www.lrdparis.com', 'Le Marais', '60 Rue Charlot', '75003', 'Paris', NULL, 'FR', 48.86366, 2.36359),
    ('devie.bar', 'De Vie', 'Bar and tasting counter in Montorgueil, opened in 2025 by Alex Francis and Barney O''Kane, formerly of Little Red Door. There is no ice: drinks are pre-batched and pre-diluted at set temperatures, and each one is named after a single seasonal ingredient from independent French producers. Named Best New International Cocktail Bar at the 2026 Spirited Awards.', 'https://devie.bar', 'Montorgueil', '22-24 Rue Saint-Sauveur', '75002', 'Paris', NULL, 'FR', 48.86618, 2.34807),
    ('harrysbar_theoriginal', 'Harry''s Bar', 'Paris''s founding American bar, opened on Rue Daunou on 26 November 1911 with a bar shipped over from Manhattan and later taken over by Scottish bartender Harry MacElhone. It claims the Bloody Mary, Sidecar, French 75 and Boulevardier among its creations. Still run by the MacElhone family, now fourth-generation Franz-Arthur, with a basement piano bar and a whisky cellar of 350-plus references.', 'https://www.harrysbar.com', 'Opéra', '5 Rue Daunou', '75002', 'Paris', NULL, 'FR', 48.86921, 2.33217),
    ('barhemingway', 'Bar Hemingway', 'Twenty-five-seat bar inside the Ritz Paris, named for Ernest Hemingway, who made the hotel''s bar his base from the 1920s. Colin Peter Field ran it for almost three decades until 2023 and created the Serendipity here. Leather armchairs, Hemingway letters and objects, no music, and a house specialty of cocktails made to order alongside a famous Dry Martini.', 'https://www.ritzparis.com/hotel/paris/bars-restaurants/bar-hemingway', 'Place Vendôme', '15 Place Vendôme', '75001', 'Paris', NULL, 'FR', 48.86879, 2.32751),
    ('candelariaparis', 'Candelaria', 'A taqueria in the Haut-Marais with a cocktail bar hidden behind an unmarked back door, opened in 2011 by the Quixotic Projects team, including Josh Fontaine and Carina Soto Velásquez. The bar is built around tequila and mezcal, and its house classic is the Guêpe Verte. Walk-in only, no reservations. A former World''s 50 Best Bars entry.', 'https://candelaria-paris.com', 'Le Marais', '52 Rue de Saintonge', '75003', 'Paris', NULL, 'FR', 48.86299, 2.36402),
    ('experimentalcocktailclub', 'Experimental Cocktail Club', 'The bar that started the Experimental Group: three childhood friends opened it on Rue Saint-Sauveur in 2007, when Paris had almost no cocktail bars, with a New York-inspired room by Cuoco Black that Dorothée Meilichzon refreshed in 2025. The seasonal list mixes house signatures with riffs on classics, resident DJs play late, and it takes no reservations.', 'https://www.experimentalgroup.com/paris/experimental-cocktail-club-paris', 'Montorgueil', '37 Rue Saint-Sauveur', '75002', 'Paris', NULL, 'FR', 48.86606, 2.34831),
    ('copperbay_paris', 'CopperBay', 'Bright, nautical-themed cocktail bar near Porte Saint-Martin, opened in October 2014 by Aurélie Panhelleux, Elfi Fabritius and Julien Lopez as a sunny alternative to dark speakeasies. Seasonal signatures sit next to pastis serves such as the Frozen Mauresque and a Hall of Fame of past hits like the Roquettini. The team has since opened in Marseille and at Hôtel Lancaster.', 'http://copperbay.fr', 'Porte Saint-Martin', '5 Rue Bouchardon', '75010', 'Paris', NULL, 'FR', 48.86984, 2.35703),
    ('lesyndicat', 'Le Syndicat', 'Behind a poster-plastered front on Rue du Faubourg Saint-Denis, Le Syndicat has used only French spirits and liqueurs since it opened in 2014, founded by Romain Le Mouellic and bartender Sullivan Doh. Cognac, armagnac, calvados and forgotten regional liqueurs go into playful cocktails, with a hip-hop soundtrack and a raw, industrial room. A former World''s 50 Best Bars entry.', 'https://www.instagram.com/lesyndicat/', 'Faubourg Saint-Denis', '51 Rue du Faubourg Saint-Denis', '75010', 'Paris', NULL, 'FR', 48.8718, 2.35362),
    ('cravanparis', 'Cravan', 'Café by day and cocktail bar by night in a listed 1911 Hector Guimard building in Auteuil that has always held a café. Historian Franck Audoux opened it in June 2018 and named it for the dada boxer-poet Arthur Cravan. Drinks are short, precise and rooted in cocktail history, led by the Yellow. A larger, four-level Cravan now also runs on Boulevard Saint-Germain.', 'https://www.cravanparis.com', 'Auteuil', '17 Rue Jean de la Fontaine', '75016', 'Paris', NULL, 'FR', 48.85166, 2.27379),
    ('argobarhk', 'Argo', 'Hotel bar inside the Four Seasons Hong Kong, opened in July 2021 and styled after a Gilded Age botanical conservatory, with a glowing cylindrical back bar and harbour views. Beverage manager Jonathan Gabbay''s current Exploration menu leans on Hong Kong makers and seasonal produce. Best International Hotel Bar at the 2026 Spirited Awards. No. 37 on Asia''s 50 Best Bars 2026.', 'https://www.fourseasons.com/hongkong/dining/lounges/argo/', 'Central', 'Four Seasons Hotel Hong Kong, 8 Finance Street', NULL, 'Hong Kong', NULL, 'HK', 22.28663, 114.15666),
    ('gokan.hk', 'Gokan', 'Japanese cocktail bar from SG Group founder Shingo Gokan, opened in 2024 with Russell Stradmoor and Amanda Cheung on Ice House Street, the site of the city''s first ice store. Drinks are sorted by the five tastes and served as a highball, on the rocks or straight up, next to izakaya-style plates. No. 22 on Asia''s 50 Best Bars 2026.', 'https://www.instagram.com/gokan.hk/', 'Central', '30 Ice House Street', NULL, 'Hong Kong', NULL, 'HK', 22.28035, 114.15644),
    ('mius.hongkong', 'Mius', 'Walk-in neighbourhood bar on Gough Street, opened in 2025 by Hong Kong-born bartender Shelley Tai after five years leading Singapore''s Nutmeg Collective. A short list of about a dozen drinks, each kept to six ingredients or fewer, sits beside grower Champagne and Cantonese comfort food. No. 36 on Asia''s 50 Best Bars 2026, where it also won Best Bar Design.', 'https://www.mius.hk/', 'Central', '29 Gough Street', NULL, 'Hong Kong', NULL, 'HK', 22.28438, 114.15237),
    ('penicillin_bar', 'Penicillin', 'Sustainability-driven bar on Hollywood Road, opened in late 2020 by Agung Prabowo and Roman Ghale of The Old Man. Billed as Hong Kong''s first closed-loop cocktail bar, it upcycles local produce and ferments ingredients in its own climate-controlled ''Stinky Room'', all in a white-tiled, lab-like room. No. 69 on The World''s 50 Best Bars 2026 (51-100).', 'https://penicillinbarhk.com/', 'Central', 'L/G, Amber Lodge, 23 Hollywood Road', NULL, 'Hong Kong', NULL, 'HK', 22.2821, 114.15399),
    ('thesavoryproject', 'The Savory Project', 'Soho bar from Jay Khan and Ajit Gurung of COA, opened in 2023 around a hexagonal counter. The menu chases savoury and umami flavours using pantry staples like miso, ponzu, shiitake and cumin, with a full non-alcoholic list alongside. Won Best New Opening at Asia''s 50 Best Bars 2024. No. 60 on Asia''s 50 Best Bars 2026.', 'https://thesavoryproject.com/', 'SoHo', '4 Staunton Street', NULL, 'Hong Kong', NULL, 'HK', 22.28156, 114.15319),
    ('montanabarhk', 'Montana', 'Party bar on Hollywood Road inspired by Cuban cocktail history and 1970s Miami, opened in summer 2025 by Lorenzo Antinori of Bar Leone and Simone Caporale of Sips. Expect Cuban-era classics like the daiquiri and El Presidente, a disco soundtrack, Latin American snacks and no reservations. New entry at No. 47 on Asia''s 50 Best Bars 2026.', 'https://www.montanabarhk.com/', 'Sheung Wan', '108 Hollywood Road', NULL, 'Hong Kong', NULL, 'HK', 22.28388, 114.15067),
    ('theoppositeshk', 'The Opposites', 'Hollywood Road bar opened in July 2024 by veteran bartenders Antonio Lai of Quinary and Samuel Kwok. The menu takes one classic at a time and serves it two ways: a balanced, classic-leaning version from Kwok and a theatrical, lab-driven take from Lai. No. 54 on Asia''s 50 Best Bars 2026, up 26 places on 2025.', 'https://www.theopposites.hk/', 'Central', 'LG/F, Hilltop Plaza, 49 Hollywood Road', NULL, 'Hong Kong', NULL, 'HK', 22.28275, 114.15309),
    ('quinaryhk', 'Quinary', 'Pioneering multisensory cocktail bar on Hollywood Road, opened in 2012 by Antonio Lai. Its long counter runs into an open lab of rotary evaporators and centrifuges used to redistill and infuse house spirits, and its Earl Grey Caviar Martini is among the city''s best-known drinks. Listed on Asia''s 50 Best Bars for an eighth time in 2024, at No. 26.', 'https://www.quinary.hk/', 'Central', 'G/F, 56-58 Hollywood Road', NULL, 'Hong Kong', NULL, 'HK', 22.28273, 114.15285),
    ('kinsman.hk', 'Kinsman', 'Cantonese cocktail salon on Peel Street, opened in late 2023 by drinks writer Gavin Yeung with Singular Concepts. Styled with nods to Wong Kar-wai films, it revives local and Chinese liquors such as Yuk Bing Siu, rose and rice wines and baijiu. Its A Tale of Chinatowns menu won Best Cocktail Menu at Asia''s 50 Best Bars 2026.', 'https://www.kinsman.hk/', 'Central', 'G/F, 65 Peel Street', NULL, 'Hong Kong', NULL, 'HK', 22.2823, 114.15213),
    ('tellcamellia', 'Tell Camellia', 'Tea-focused cocktail bar tucked into the H Code building, opened in 2019 by bar veterans Sandeep Hathiramani and Gagan Gurung and now helmed by Gurung. Teas from sencha and hojicha to lapsang and white peony are brewed, infused or redistilled into nearly every drink. Back on Asia''s 50 Best Bars in 2026 at No. 81.', 'https://www.tellcamellia.hk/', 'Central', 'Shop 2, LG/F, H Code, 45 Pottinger Street', NULL, 'Hong Kong', NULL, 'HK', 22.28229, 114.15432),
    ('fura.sg', 'FURA', 'Sustainability-led cocktail bar and kitchen upstairs in an Amoy Street shophouse, opened in October 2023 by Christina Rasmussen, formerly head forager at Noma, and Sasha Wijidessa, ex-head bartender of Operation Dagger. Drinks and plates lean on foraged, fermented and ''future protein'' ingredients such as insects and jellyfish. Named World''s Best Bar at the 2026 Spirited Awards.', 'https://www.fura.space', 'Telok Ayer', '74A Amoy Street, Level 2', '069893', 'Singapore', NULL, 'SG', 1.28036, 103.84662),
    ('offtrack.sg', 'Offtrack', 'Music-first bar and restaurant on North Canal Road, opened in January 2022 by Dean Chew of Darker Than Wax and Daniel O''Connor of Ice Cream Sundays. A tuned sound system and vinyl from Singapore and the region set the tone, the drinks list splits evenly between reworked classics and house cocktails under head bartender Joash Conceicao, and the food is pan-Asian sharing plates. No. 16 on Asia''s 50 Best Bars 2026.', 'https://www.offtrack.sg', 'Boat Quay', '34 North Canal Road', '059290', 'Singapore', NULL, 'SG', 1.28701, 103.84725),
    ('nativebarsg', 'Native', 'Vijay Mudaliar''s Amoy Street bar, open since late 2016, built around spirits and produce from Singapore and Southeast Asia, much of it foraged, with a low-waste approach and no classic cocktails on the menu. Its first list introduced the Antz, a rum drink topped with ants. The bar sits upstairs, with a restaurant serving regional comfort food below. No. 80 on Asia''s 50 Best Bars 2026.', 'https://www.tribenative.com', 'Telok Ayer', '52A Amoy Street', '069878', 'Singapore', NULL, 'SG', 1.28017, 103.84686),
    ('originbarsg', 'Origin Bar', 'Travel-themed lobby bar in the Tower Wing of Shangri-La Singapore, opened in 2017 and styled like a vintage railway lounge in gold, deep blue and dark wood. Set up by Adam Bursik after stints at Nutmeg & Clove and The Library, it rebuilds its menu around one team-wide idea every year or so and keeps a back bar of some 600 spirits, heavy on rum. No. 43 on Asia''s 50 Best Bars 2026.', 'https://www.originbar.sg', 'Tanglin', '22 Orange Grove Road, Shangri-La Singapore (Tower Wing, Lobby Level)', '258350', 'Singapore', NULL, 'SG', 1.31148, 103.82644),
    ('catbiteclub', 'Cat Bite Club', 'Agave and rice spirits bar hidden behind a curtain inside a Duxton Road cafe, opened in June 2023 by San Francisco-raised childhood friends Gabriel Lowe and Jesse Vida. Classics are reworked with tequila, mezcal, soju, shochu and baijiu drawn from more than 300 bottles from Mexico and Asia. Won the One To Watch award at The World''s 50 Best Bars 2024, where it ranked No. 56.', 'https://catbiteclub.com', 'Duxton', '75 Duxton Road', '089534', 'Singapore', NULL, 'SG', 1.27836, 103.84309),
    ('sidedoor_sg', 'Side Door', 'Neighbourhood cocktail bar and kitchen on Neil Road run by husband-and-wife Bannie Kang, the 2019 Diageo World Class global champion, and chef Tryson Quek. It began as a tiny private supper club in their home before moving into a 40-seat space in late 2023, where Kang''s pared-back takes on classics are paired with Quek''s small plates. No. 57 on Asia''s 50 Best Bars 2026.', 'https://www.instagram.com/sidedoor_sg/', 'Tanjong Pagar', '3 Neil Road, #01-01', '088805', 'Singapore', NULL, 'SG', 1.28018, 103.84376),
    ('elephantroomsg', 'The Elephant Room', 'Bar founded in 2019 by Yugnes Susela, formerly of Smoke & Mirrors, that draws every drink from Little India: spices, produce and dishes sourced around Tekka market become cocktails such as a clarified curry drink, a biryani riff and a ghee-washed sour, served with Indian bar bites in a room on Tanjong Pagar Road. No. 58 on Asia''s 50 Best Bars 2026.', 'https://www.theelephantroom.sg', 'Tanjong Pagar', '33 Tanjong Pagar Road, #01-02', '088456', 'Singapore', NULL, 'SG', 1.27916, 103.8441),
    ('atlasbarsg', 'ATLAS', 'Grand Art Deco lobby bar on the ground floor of Parkview Square, opened in 2017 by the Parkview Group. Its towering gin display holds more than 1,300 gins, some dating to the early 1900s, alongside one of Asia''s largest Champagne lists, and the ATLAS Martini is the house signature. Asia''s 50 Best Bars Legend of the List in 2024 and No. 43 on The World''s 50 Best Bars 2024.', 'https://atlasbar.sg', 'Bugis', '600 North Bridge Road, Parkview Square', '188778', 'Singapore', NULL, 'SG', 1.3001, 103.85771),
    ('longbarsg', 'Long Bar', 'The Raffles Hotel bar where bartender Ngiam Tong Boon created the Singapore Sling in 1915. It now occupies the second floor of the Raffles Arcade, decorated in the style of 1920s Malayan plantation life, and guests still brush peanut shells onto the floor. The Sling is made today with locally distilled Brass Lion Singapura Gin, and there is an alcohol-free version.', 'https://www.raffles.com/singapore/dining/long-bar/', 'City Hall', '328 North Bridge Road, #02-01 Raffles Arcade', '188719', 'Singapore', NULL, 'SG', 1.29513, 103.85347),
    ('bop_bartendersofpony', 'BOP (Bartenders of Pony)', 'Korean cocktail dining bar in a Tras Street shophouse, opened in early 2026 by the Jigger & Pony Group and led by group creative director Uno Jang. Familiar cocktail templates are rebuilt with soju, makgeolli, rice nuruk, perilla and seaweed, alongside iced somaek and Korean bar food from chef David Tang with Jason Oh. It debuted at No. 52 on Asia''s 50 Best Bars 2026.', 'https://bartendersofpony.com', 'Tanjong Pagar', '76 Tras Street', '079015', 'Singapore', NULL, 'SG', 1.2774, 103.84406),
    ('cantina.ok', 'Cantina OK!', 'A standing-room-only mezcal bar for about 20 people, set in a converted garage down Council Place, a short laneway off Clarence Street. Opened in 2019 by Jeremy Blackmore and Alex Dowd of Tio''s Cerveceria (now MUCHO Group), it pours hand-sourced agave spirits and margaritas over hand-cranked shaved ice. No. 96 on The World''s 50 Best Bars 2024.', 'https://www.muchogroup.com.au/cantinaok', 'CBD', 'Council Place', '2000', 'Sydney', 'New South Wales', 'AU', -33.87027, 151.20505),
    ('barplanetbar', 'Bar Planet', 'A playful, space-age martini bar at the Newtown end of Enmore Road, opened in 2022 by the MUCHO Group team behind Cantina OK! (Jeremy Blackmore, Alex Dowd and Daisy Tulley). The house martini is built on a seasonal in-house spirit and poured from height out of a porrón, alongside a short list of fresh, fruit-led cocktails. Australian Gin Bar of the Year in 2025 and 2026.', 'https://www.muchogroup.com.au/barplanet', 'Newtown', '16 Enmore Road', '2042', 'Sydney', 'New South Wales', 'AU', -33.89821, 151.17764),
    ('oldmatesplace', 'Old Mate''s Place', 'A two-level bar on the top floor of 199 Clarence Street, with a whisky- and rum-heavy back bar downstairs and a hidden rooftop above. Opened in August 2018 by Andres and Gabrielle Walters and Daniel Noble, it is loved by the trade for fun, fruit-forward drinks and easygoing service. Australian Bar of the Year 2025 and Best Bartenders'' Bar 2026.', 'https://oldmates.sydney/', 'CBD', 'Level 4, 199 Clarence Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.86937, 151.20509),
    ('oldlovessyd', 'Old Love''s', 'A tiki-leaning rum bar in the basement of 199 Clarence Street, opened in late 2023 by the Old Mate''s Place team led by Dre Walters. Guests get a house ''Book of Rum'', the back bar is shelved in the same order as the book, and the drinks revive old Caribbean and Pacific recipes. Rum Bar of the Year 2024, 2025 and 2026; its Callum Marra was 2026 Australian Bartender of the Year.', 'https://www.oldloves.sydney', 'CBD', 'Basement, 199 Clarence Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.86963, 151.2052),
    ('deanandnancyon22', 'Dean & Nancy on 22', 'A mid-century style hotel bar on level 22 of A by Adina Sydney, opened in 2021 and run with the Maybe Sammy team. Black and gold interiors, a brass staircase, a grand piano and skyline views frame the ''Time Machine'' list of cocktails inspired by 1950s and 60s legends and pop culture. Australian Hotel Bar of the Year in 2024 and 2025.', 'https://www.deanandnancyon22.com.au/', 'CBD', 'Level 22, 2 Hunter Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.86534, 151.20755),
    ('bartilda.sydney', 'Bar Tilda', 'A moody, marble-clad hotel bar off Phillip Street in the Sofitel Sydney Wentworth, opened in October 2024 by House Made Hospitality with drinks by Jason Williams and Christian Blair. Its showpieces are an armoire holding more than 100 Australian whiskies and an Archie Rose martini trolley mixed at the table, plus live music. Australian Hotel Bar of the Year 2026.', 'https://www.bartilda.sydney/', 'CBD', '61-101 Phillip Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.8655, 151.21102),
    ('ramblinrascaltavern', 'Ramblin'' Rascal Tavern', 'A self-styled five-star dive bar in a basement near the corner of Park and Elizabeth Streets, marked only by a sign with three skulls. Opened in 2014 by former Swillhouse bartenders Charlie Lehmann, Dardan Shervashidze and Sebastian Soto, it pairs a deep cognac and whisky back bar with cheap tins, sharp cocktails and live music four nights a week. Best Bartenders'' Bar 2025.', 'https://www.ramblinrascal.com/', 'CBD', '199 Elizabeth Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.87309, 151.20971),
    ('thebaxterinnsydney', 'The Baxter Inn', 'The basement whisky bar that helped define Sydney''s small-bar era, hidden at the end of an alley off Clarence Street. Opened in 2011 by Swillhouse founders Anton Forte and Jason Scott, it is known for a towering wall of whisky, staff happy to talk through any bottle, pretzels and a short list of seasonal house cocktails. Walk-in only, open until 3am.', 'https://swillhouse.com/venues/the-baxter-inn/', 'CBD', 'Basement, 152-156 Clarence Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.86975, 151.20553),
    ('ps40bar', 'PS40', 'A cocktail bar and soda lab off Skittle Lane in the CBD, opened in 2016 by Michael Chiem and Thor Bergquist and owned solely by Chiem since 2019. House sodas such as wattle cola and bush tonic are made and poured on tap, and the list applies kitchen techniques to native Australian flavours. Its signature Africola remains one of the city''s best-known drinks.', 'https://ps40bar.com/', 'CBD', 'Shop 2, 40 King Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.86858, 151.20479),
    ('deadwax.enmore', 'Deadwax', 'A Japanese-inspired vinyl listening bar on Enmore Road, opened in August 2025 by Conor O''Brien and Dan Teh of Otis. Hi-fi sound, a large record library, DJs at weekends and a bar top made from 70 layers of resin-soaked denim set the scene for Japanese-leaning riffs on classics, a big Japanese whisky range and late-night snacks. A 2026 finalist for Australia''s New Bar of the Year.', 'https://www.deadwaxbar.com.au/', 'Enmore', '182 Enmore Road', '2042', 'Sydney', 'New South Wales', 'AU', -33.8992, 151.17218),
    ('apolloniabar', 'Apollonia', 'A basement bar beneath Hinchcliff House near Circular Quay, imagined as a Sicilian bandit''s drinking den and named for Apollonia from The Godfather. Opened in April 2021 by House Made Hospitality, with drinks overseen by former Australian Bartender of the Year Jason Williams, it is known for Negronis and an Italian-leaning ''Playbill'' menu told in four acts.', 'https://apollonia.sydney/', 'Circular Quay', 'Basement, 5-7 Young Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.86252, 151.21095),
    ('aboveboardbarmelb', 'Above Board', 'Seated-only cocktail bar up a laneway stair off Smith Street, opened in 2016 by Hayden Lambert, a veteran of Belfast''s Merchant Hotel and Melbourne''s Bar Americano, with partners Manu Potoi and Cornelis Ribbe. The bottles stay hidden and the list keeps to about 25 carefully tuned signatures and classics. Australian Cocktail Bar of the Year 2024 and Small Bar of the Year 2026.', 'https://www.aboveboardbar.com', 'Collingwood', 'Level 1, 306 Smith Street', '3066', 'Melbourne', 'Victoria', 'AU', -37.80009, 144.98443),
    ('threehorsesbar', 'Three Horses', 'Sherry-led cocktail bar on Little Lonsdale Street from Matt Stirling, Ryan Noreiks and Rob Libecans, the team behind Caretaker''s Cottage a few doors down. Opened in September 2025 in the old Troika space and inspired by Madrid''s sherry bodegas, it pours a rotating sherry list next to sherry-seasoned cocktails such as the tableside Jabberwock. No. 84 on The World''s 50 Best Bars 2026 (51-100).', 'https://www.threehorses.bar', 'Melbourne CBD', '106 Little Lonsdale Street', '3000', 'Melbourne', 'Victoria', 'AU', -37.80921, 144.96869),
    ('blackpearlfitzroy', 'Black Pearl', 'Brunswick Street institution that has anchored Fitzroy''s bar scene for more than two decades, owned by Tash Conte and long known as a training ground for Australian bartending talent. The downstairs bar is walk-in and runs until 3am, while The Attic upstairs takes bookings. The Death Flip was created here in 2010, and the bar held a place on The World''s 50 Best Bars list from 2009 to 2018.', 'https://www.blackpearlbar.com.au', 'Fitzroy', '304 Brunswick Street', '3065', 'Melbourne', 'Victoria', 'AU', -37.79807, 144.97875),
    ('gimlet.melbourne', 'Gimlet at Cavendish House', 'Andrew McConnell''s grand cocktail bar and dining room inside Cavendish House, a heritage building on the corner of Russell Street and Flinders Lane, opened in 2020 by his Trader House group. Known for its namesake Gimlet, a polished martini list and European-leaning food served late into the night. Restaurant Bar of the Year at the 2025 Australian Bar Awards.', 'https://gimlet.melbourne', 'Melbourne CBD', '33 Russell Street', '3000', 'Melbourne', 'Victoria', 'AU', -37.81588, 144.96931),
    ('apolloinn.bar', 'Apollo Inn', 'Intimate Flinders Lane cocktail bar from Andrew McConnell and Jo McGann of Trader House, opened in June 2023 as a small sibling to Gimlet and named after one of Melbourne''s first public houses, which stood on the nearby corner in 1844. Leather doors, a European-style room and a martini-led list of old-world classics with a modern touch. New Bar of the Year at the 2024 Australian Bar Awards.', 'https://apolloinn.bar', 'Melbourne CBD', '165 Flinders Lane', '3000', 'Melbourne', 'Victoria', 'AU', -37.81597, 144.96898),
    ('bar.bellamy', 'Bar Bellamy', 'Warm neighbourhood bistro and cocktail bar on leafy Rathdowne Street in Carlton, opened in May 2023 by married couple Dani and Oska Whitehart. Communal tables, a seasonal European menu and small-batch cocktails that rotate several times a week, with inventive martini twists a speciality. Best Bar Food winner at the 2025 Australian Bar Awards.', 'https://barbellamy.com', 'Carlton', '164 Rathdowne Street', '3053', 'Melbourne', 'Victoria', 'AU', -37.79547, 144.97113),
    ('goodwater.melbourne', 'Goodwater', 'American whiskey and cocktail bar on High Street in Northcote, opened in early 2024 by a crew of bartenders and drinks writers led by Nathaniel White, including Cara Devine and Fred Siggins. Named after the Native American name for the Ohio River, it stocks around 200 American whiskeys and pairs them with modern classics and sandwiches. Small Bar of the Year at the 2025 Australian Bar Awards.', 'https://goodwater.melbourne', 'Northcote', '300 High Street', '3070', 'Melbourne', 'Victoria', 'AU', -37.77136, 144.99876),
    ('ginpalacemelb', 'Gin Palace', 'Russell Place laneway bar opened by Vernon Chalker in 1997, reviving the name of a notorious Melbourne gin house shut down in 1870 and helping start the city''s small-bar era. Now part of the Vespertine group, it stocks more than 330 gins, pours long 90ml martinis and serves its famous toasted chicken sandwiches until close. Gin Bar of the Year at the 2024 Australian Bar Awards.', 'https://www.ginpalace.com.au', 'Melbourne CBD', '10 Russell Place', '3000', 'Melbourne', 'Victoria', 'AU', -37.81384, 144.96749),
    ('pendant.publicbar', 'Pendant Public Bar', 'Fitzroy neighbourhood bar on Brunswick Street from Belinda Linton and Luke Kelly, whose resumes include Black Pearl, The Everleigh, Apollo Inn and Mr West. Opened in 2025 in the former Enoteca Zingara site, it mixes old Irish pub with New Orleans cocktail bar: Guinness on tap, a very dry house martini, a short list of classics and live bluegrass on Sundays. New Bar of the Year at the 2025 Australian Bar Awards.', 'https://www.pendantpublicbar.com', 'Fitzroy', '334 Brunswick Street', '3065', 'Melbourne', 'Victoria', 'AU', -37.7973, 144.97887),
    ('handsdownmelbourne', 'Hands Down', 'Loud, fun Greeves Street bar in Fitzroy from Dominic Xavier (Bar Liberty) with Hayden Lambert and Manu Potoi (Above Board), run by Alex Boon of Pearl Diver. Opened in November 2025 in the former Bad Frankie space, it pours a dozen vermouth- and sherry-leaning cocktails inspired by the coasts of southern France and northern Spain, with gildas at the bar and a 40-seat parklet outside.', 'https://www.handsdownmelbourne.com', 'Fitzroy', '139-141 Greeves Street', '3065', 'Melbourne', 'Victoria', 'AU', -37.80032, 144.98375),
    ('bar1806', '1806', 'Theatre-district cocktail bar on Exhibition Street, opened in 2007 and named for the year the word cocktail was first defined in print. Set in a building that once housed a theatre restaurant, it pairs an ornate old-world room with a deep classics list and a menu of story-driven house signatures, and it was on the first World''s 50 Best Bars list in 2009.', 'https://www.1806.com.au', 'Melbourne CBD', '169 Exhibition Street', '3000', 'Melbourne', 'Victoria', 'AU', -37.81162, 144.97013)
) AS v("handle", "name", "bio", "website", "locality", "address_line", "postcode", "city", "region", "country_code",
       "latitude", "longitude")
-- Not a second copy of a bar someone already added (add_venue's rule).
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."profiles" p
    WHERE p.kind = 'bar' AND p.latitude BETWEEN v.latitude - 0.002 AND v.latitude + 0.002
      AND private.venue_name_key(p.display_name) = private.venue_name_key(v.name)
      AND private.distance_km(v.latitude, v.longitude, p.latitude, p.longitude) <= 0.15
)
ON CONFLICT ("handle") DO NOTHING;

